    }

    function run(address target, uint256 amount) public {
        assert(c.owner() == address(this));

        uint256 supplyBefore = c.totalSupply();
        uint256 targetBalBefore = c.balanceOf(target);

        bool reverted;
        try c.mintToken(target, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            (!reverted
                && c.totalSupply() == supplyBefore + amount
                && c.balanceOf(target) == targetBalBefore + amount)
            || (reverted
                && c.totalSupply() == supplyBefore
                && c.balanceOf(target) == targetBalBefore)
        );
    }

    receive() external payable {}
}

